    var body: some View {
        HStack(spacing: 12) {
            NativeIcon(symbol: suggestion.mutual ? "person.2.circle.fill" : "person.crop.circle", color: suggestion.mutual ? NativeTheme.purple : NativeTheme.cyan)
            VStack(alignment: .leading, spacing: 3) {
